INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, "訓練はまだ\nここからですわ", "vo_minigame_1013_icon_2_002_001", 1000, 1, 2, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_1_002_001", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, "クスクス、悪くない\n流れですわね", "vo_minigame_1013_icon_2_003_001", 5000, 2, 2, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_1_003_001", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "すばらしい\n記録ですわ", "vo_minigame_1013_icon_2_004_001", 10000, 3, 2, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_1_004_001", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "乗りに乗って\nいますわね", "vo_minigame_1013_icon_2_005_001", 10000, 4, 3, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_1_005_001", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "まだまだ行きます\nついてきなさい", "vo_minigame_1013_icon_2_005_002", 10000, 5, 3, "見てろよ！\nマコト班の快進撃だ！", "vo_minigame_1013_icon_1_005_002", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "エリコ班の\n本領発揮ですわ！", "vo_minigame_1013_icon_2_005_003", 10000, 6, 3, "うおぉぉっ！\n絶好調だぜ！", "vo_minigame_1013_icon_1_005_003", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "ここからは\n前人未到の領域です！", "vo_minigame_1013_icon_2_006_001", 0, 7, 4, "どこまで行けるか\n楽しみだなっ！", "vo_minigame_1013_icon_1_006_001", 3000, 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, "厄介でしたわ…", "vo_minigame_1013_icon_2_007_001", 1, 8, 5, "まだ諦めんなよっ", "vo_minigame_1013_icon_1_007_001", 1000, 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, "油断大敵です", "vo_minigame_1013_icon_2_007_002", 1, 9, 5, "冷やっとしたぜ…！", "vo_minigame_1013_icon_1_007_002", 1000, 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, "忌々しいっ…", "vo_minigame_1013_icon_2_007_003", 1, 10, 5, "弱音を吐くなっ", "vo_minigame_1013_icon_1_007_003", 1000, 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "大所帯ですわね", "vo_minigame_1013_icon_2_008_001", 99, 11, 6, "マコト班集合！", "vo_minigame_1013_icon_1_008_001", 1500, 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, "エリコ班へようこそ", "vo_minigame_1013_icon_2_008_002", 99, 12, 6, "連携してくぞ！", "vo_minigame_1013_icon_1_008_002", 1500, 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (6, "ナナカちゃんに\nお任せあれ", "vo_minigame_1013_icon_2_020_001", 0, 13, 8, "みんなに力を！", "vo_minigame_1013_icon_1_020_001", 3000, 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (7, "はっはっは！\n任せろ！", "vo_minigame_1013_icon_2_022_001", 0, 14, 9, "任せてくれたまえ", "vo_minigame_1013_icon_1_022_001", 3000, 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (8, "どんどんいくわよ", "vo_minigame_1013_icon_2_023_001", 0, 15, 10, "ほな、いきまひょか", "vo_minigame_1013_icon_1_023_001", 3000, 1);
